param([switch]$CpuStagePreflightFixture,[switch]$CpuPacketFixture)
$ErrorActionPreference = 'Stop'
if ($PSVersionTable.PSVersion.Major -lt 7) { throw 'Run this supervisor with PowerShell 7 or newer' }
$ArtifactDir = $PSScriptRoot
$JobPath = Join-Path $ArtifactDir 'native-job.json'
$AdmissionPath = Join-Path $ArtifactDir 'native-admission.json'
$Stage = 'C:\CodexTemp\tetherbound-native-service'
$OutputRoot = 'D:\tetherbound\.artifacts\s'
$OwnerPath = 'C:\CodexTemp\tetherbound-native-owner.json'
$OwnerLockPath = 'C:\CodexTemp\tetherbound-native-owner.lock'
$ExpectedThread = '01a13307-fea3-7ae0-a0cf-ecd8f0e0d502'
$ExpectedSource = 'ed334586415bf3317fc85f0a6aa352ffe93d2095'
$Engine = 'C:\Users\mattj\.cache\tetherbound-tools\godot-4.7\Godot_v4.7-stable_win64.exe'
$EngineSha = 'b2ca888d5115a6cedee564764a2ee494a625f2ec2edbabd010fe33c9a88a6bf8'
$Git = 'C:\Users\mattj\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\git\cmd\git.exe'
$CAdmissionFloor = 10.5GB
$CStopFloor = 10GB
$DAdmissionFloor = 21GB
$DStopFloor = 20GB
$MemoryFloor = 2GB
$CombinedLogsCap = 32MB
$OutputCap = 160MB
$PacketCap = 16MB
$script:OwnerLock = $null
$script:Proc = $null
$script:ProcId = $null
$script:ProcStartUtc = $null
$script:RunnerPid = [Diagnostics.Process]::GetCurrentProcess().Id
$script:CommandLine = $null
$script:OutStream = $null
$script:ErrStream = $null
$script:OutTask = $null
$script:ErrTask = $null
$script:LeaseOwned = $false
$script:LeaseRun = $null
$script:LeasePid = 0
$script:CurrentStepId = $null
$script:ObservedStopReason = $null
$script:StepReceipts = @()
$script:LogPaths = @()
$script:MinPhysical = [long]::MaxValue
$script:MinCommit = [long]::MaxValue
$script:MinC = [long]::MaxValue
$script:MinD = [long]::MaxValue

function Read-Json([string]$Path) { Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json }
function Write-JsonAtomic([string]$Path, $Value) {
    $Temp = "$Path.$([Guid]::NewGuid().ToString('N')).tmp"
    $Value | ConvertTo-Json -Depth 24 | Set-Content -LiteralPath $Temp -Encoding utf8
    if (Test-Path -LiteralPath $Path -PathType Leaf) { $Backup="$Path.$([Guid]::NewGuid().ToString('N')).bak"; [IO.File]::Replace($Temp, $Path, $Backup); Remove-Item -LiteralPath $Backup -Force } else { [IO.File]::Move($Temp, $Path) }
}
function Hash-File([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Assert-Hash([string]$Path,[string]$Expected) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "Pinned file is missing: $Path" }
    if ((Hash-File $Path) -cne $Expected.ToLowerInvariant()) { throw "SHA-256 mismatch: $Path" }
}
function Invoke-Git([string[]]$GitArgs) {
    $OldLazy=$env:GIT_NO_LAZY_FETCH; $OldOptional=$env:GIT_OPTIONAL_LOCKS
    try { $env:GIT_NO_LAZY_FETCH='1'; $env:GIT_OPTIONAL_LOCKS='0'; $Text=@(& $Git -C $Stage -c core.fsmonitor=false -c core.preloadindex=false @GitArgs 2>&1); $Code=$LASTEXITCODE }
    finally {
        if ($null -eq $OldLazy) { Remove-Item Env:GIT_NO_LAZY_FETCH -ErrorAction SilentlyContinue } else { $env:GIT_NO_LAZY_FETCH=$OldLazy }
        if ($null -eq $OldOptional) { Remove-Item Env:GIT_OPTIONAL_LOCKS -ErrorAction SilentlyContinue } else { $env:GIT_OPTIONAL_LOCKS=$OldOptional }
    }
    if ($Code -ne 0) { throw "No-lazy-fetch Git command failed: $($GitArgs -join ' ')" }
    return $Text
}
function Get-FreeBytes([string]$Drive) {
    $Info=[IO.DriveInfo]::new("$Drive`:\")
    if (-not $Info.IsReady) { throw "Drive $Drive`: unavailable" }
    return [long]$Info.AvailableFreeSpace
}
function Get-Memory {
    $Os=Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
    $Mem=Get-CimInstance Win32_PerfRawData_PerfOS_Memory -ErrorAction Stop
    if ($null -eq $Os.FreePhysicalMemory -or $null -eq $Mem.CommitLimit -or $null -eq $Mem.CommittedBytes) { throw 'Physical or commit counters unavailable' }
    return @{physical=[long]$Os.FreePhysicalMemory*1024;commit=[long]$Mem.CommitLimit-[long]$Mem.CommittedBytes}
}
function Assert-Resources([bool]$Admission=$false) {
    $C=Get-FreeBytes 'C'; $D=Get-FreeBytes 'D'; $M=Get-Memory
    $script:MinC=[Math]::Min($script:MinC,$C); $script:MinD=[Math]::Min($script:MinD,$D)
    $script:MinPhysical=[Math]::Min($script:MinPhysical,[long]$M.physical); $script:MinCommit=[Math]::Min($script:MinCommit,[long]$M.commit)
    if ($Admission -and $C -lt $CAdmissionFloor) { throw 'C: below 10.5 GiB admission reserve' }
    if ($C -lt $CStopFloor) { throw 'C: below 10 GiB stop floor' }
    if ($Admission -and $D -lt $DAdmissionFloor) { throw 'D: below 21 GiB admission reserve' }
    if ($D -lt $DStopFloor) { throw 'D: below 20 GiB stop floor' }
    if ($M.physical -lt $MemoryFloor) { throw 'Available physical memory below 2 GiB' }
    if ($M.commit -lt $MemoryFloor) { throw 'Commit headroom below 2 GiB' }
    return $M
}
function Get-EngineRows {
    return @(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object { $_.Name -match '^(Godot.*|Blender.*)\.exe$' })
}
function Assert-NoForeignEngine([int]$AllowedPid=0) {
    $Rows=@(Get-EngineRows | Where-Object { [int]$_.ProcessId -ne $AllowedPid })
    if ($Rows.Count -gt 0) { throw ('Other engine process active: ' + (($Rows | ForEach-Object { "$($_.Name):$($_.ProcessId)" }) -join ', ')) }
}
function Get-RunBytes([string]$Path) {
    [long]$Total=0
    if (-not (Test-Path -LiteralPath $Path)) { return 0 }
    foreach ($File in Get-ChildItem -LiteralPath $Path -File -Force -Recurse) { $Total += [long]$File.Length }
    return $Total
}
function Get-CombinedLogBytes {
    [long]$Total=0
    foreach ($Path in $script:LogPaths) { if (Test-Path -LiteralPath $Path -PathType Leaf) { $Total += [long](Get-Item -LiteralPath $Path).Length } }
    return $Total
}
function Assert-Source {
    $null=Invoke-Git @('cat-file','-e',($ExpectedSource+'^{commit}') )
    $Parent=(Invoke-Git @('rev-parse',($ExpectedSource+'^')) | Select-Object -First 1).Trim()
    if ($Parent -cne $Job.source_parent) { throw 'Pinned immediate parent differs' }
    $Changed=@(Invoke-Git @('diff','--name-only',[string]$Job.staging_base,$ExpectedSource))
    if (($Changed -join "`n") -cne ($Job.changed_source_paths -join "`n")) { throw 'Pinned changed path metadata differs' }
    $Head=(Invoke-Git @('rev-parse','HEAD') | Select-Object -First 1).Trim()
    if ($Head -cne $ExpectedSource) { throw "Native HEAD must be $ExpectedSource (found $Head)" }
    if (@(Invoke-Git @('status','--porcelain','--untracked-files=no')).Count -gt 0) { throw 'Tracked native source is dirty' }
    $TreeArgs=@('ls-tree','-r',$ExpectedSource,'--')+@($Job.source_bindings | ForEach-Object { [string]$_.path })
    $Tree=@{}
    foreach($Line in @(Invoke-Git $TreeArgs)) {
        if ($Line -notmatch '^100[0-7]{3} blob ([0-9a-f]{40})\t(.+)$') { throw 'Unexpected pinned tree entry' }
        if ($Tree.ContainsKey($Matches[2])) { throw 'Duplicate pinned tree entry' }
        $Tree[$Matches[2]]=$Matches[1]
    }
    if ($Tree.Count -ne $Job.source_bindings.Count) { throw 'Pinned tree entry count differs' }
    foreach ($Binding in $Job.source_bindings) {
        $Blob=$Tree[[string]$Binding.path]
        if ($Blob -cne [string]$Binding.blob) { throw "Git blob mismatch: $($Binding.path)" }
        $SourcePath=Join-Path $Stage ([string]$Binding.path)
        if ([IO.Path]::GetExtension($SourcePath) -in @('.glb','.bin')) {
            $Digest=Hash-File $SourcePath
        } else {
            $Text=[IO.File]::ReadAllText($SourcePath).Replace("`r`n","`n")
            $Digest=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($Text))).ToLowerInvariant()
        }
        if ($Digest -cne [string]$Binding.sha256) { throw "Canonical source SHA mismatch: $($Binding.path)" }
    }
}
function Read-Owner { Read-Json $OwnerPath }
function Claim-Owner([string]$RunId) {
    $Owner=Read-Owner
    if ($Owner.thread -cne $ExpectedThread -or $Owner.reserved -ne $true -or $Owner.allow_native_launch -ne $true -or $Owner.active_process_id -or $Owner.active_session_id -or $Owner.run_id -or @($Owner.processes).Count -gt 0) { throw 'Exact native lease is not idle/reserved for prelaunch claim' }
    $Owner.active_process_id=$script:RunnerPid; $Owner.active_session_id=$null; $Owner.active_kind='hall_night_medium_starting'
    $Owner.processes=@(@{pid=$script:RunnerPid;kind='hall_night_medium_supervisor'}); $Owner.run_id=$RunId
    $Owner.run_directory=$RunDir; $Owner.source=$ExpectedSource; $Owner.purpose='Hall contact-v2 paired lighting diagnostic; process starting'
    $Owner.updated_utc=[DateTime]::UtcNow.ToString('o'); Write-JsonAtomic $OwnerPath $Owner
    $script:LeaseOwned=$true; $script:LeaseRun=$RunId; $script:LeasePid=$script:RunnerPid
}
function Record-OwnedChild([int]$PidValue,[DateTime]$CreatedUtc,[string]$RunId) {
    $Owner=Read-Owner
    if ($Owner.thread -cne $ExpectedThread -or $Owner.reserved -ne $true -or $Owner.run_id -cne $RunId -or [int]$Owner.active_process_id -ne $script:RunnerPid) { throw 'Prelaunch lease changed before recording child identity' }
    $Owner.active_process_id=$PidValue; $Owner.active_kind='hall_night_medium_witness'
    $Owner.processes=@(@{pid=$PidValue;kind='hall_night_medium_witness';created_utc=$CreatedUtc.ToString('o')})
    $Owner.purpose='Hall contact-v2 paired lighting diagnostic; owned child recorded'
    $Owner.updated_utc=[DateTime]::UtcNow.ToString('o'); Write-JsonAtomic $OwnerPath $Owner
    $script:LeasePid=$PidValue
}
function Update-Owner([bool]$Release,[int]$PidValue=0,[string]$RunId='') {
    $Owner=Read-Owner
    if ($Owner.thread -cne $ExpectedThread -or $Owner.reserved -ne $true -or $Owner.allow_native_launch -ne $true) { throw 'Exact native lease authorization changed' }
    if ($Release) {
        if ([int]$Owner.active_process_id -ne $PidValue -or $Owner.run_id -cne $RunId) { throw 'Refusing to release another run lease' }
        $Owner.active_process_id=$null; $Owner.active_session_id=$null; $Owner.active_kind=$null; $Owner.processes=@(); $Owner.run_directory=$null; $Owner.run_id=$null
        $Owner.purpose='Service lane reserved; no native writer'; $Owner.source=$ExpectedSource
    } else {
        if ($Owner.active_process_id -or $Owner.active_session_id -or $Owner.run_id -or @($Owner.processes).Count -gt 0) { throw 'Root lease is not idle' }
        $Owner.active_process_id=$PidValue; $Owner.active_session_id=$null; $Owner.active_kind='hall_night_medium_witness'
        $Owner.processes=@(@{pid=$PidValue;kind='hall_night_medium_witness'}); $Owner.run_id=$RunId
        $Owner.run_directory=$RunDir; $Owner.source=$ExpectedSource; $Owner.purpose='Hall contact-v2 paired lighting diagnostic'
    }
    $Owner.updated_utc=[DateTime]::UtcNow.ToString('o')
    Write-JsonAtomic $OwnerPath $Owner
}
function Assert-OwnedCim {
    if (-not $script:Proc) { throw 'No owned process handle' }
    if ($script:Proc.HasExited) { return $null }
    $Rows=@(Get-CimInstance Win32_Process -Filter "ProcessId = $script:ProcId" -ErrorAction SilentlyContinue)
    if ($Rows.Count -ne 1) { $script:Proc.Refresh(); if ($script:Proc.HasExited) { return $null }; throw 'Owned live process CIM identity unavailable' }
    $Row=$Rows[0]
    if ([string]::IsNullOrWhiteSpace([string]$Row.ExecutablePath)) {
        $script:Proc.Refresh()
        if ($script:Proc.HasExited) { return $null }
        throw 'Owned live process executable identity unavailable; refusing termination'
    }
    if ([int]$Row.ParentProcessId -ne $script:RunnerPid -or [IO.Path]::GetFullPath([string]$Row.ExecutablePath) -cne [IO.Path]::GetFullPath($Engine) -or [string]$Row.CommandLine -cne $script:CommandLine) { throw 'Owned process parent, image or full command line changed; refusing termination' }
    $Creation=if ($Row.CreationDate -is [DateTime]) {$Row.CreationDate.ToUniversalTime()} else {[Management.ManagementDateTimeConverter]::ToDateTime([string]$Row.CreationDate).ToUniversalTime()}
    if ([Math]::Abs(($Creation-$script:ProcStartUtc).TotalSeconds) -gt 1.0) { throw 'Owned process creation time changed; refusing termination' }
    return $Row
}
function Stop-OwnedProcess([string]$Reason,[switch]$InjectFailureForCpuFixture) {
    if (-not $script:Proc -or $script:Proc.HasExited) { return }
    if ($InjectFailureForCpuFixture) { throw 'Injected Stop-OwnedProcess failure (CPU fixture only)' }
    # Before CIM readiness the held Process handle is the only trustworthy
    # identity; it came directly from this supervisor's Process.Start call.
    if (-not [string]::IsNullOrWhiteSpace([string]$script:CommandLine)) { $null=Assert-OwnedCim }
    if ($script:Proc.HasExited) { return }
    $script:Proc.Kill()
    if (-not $script:Proc.WaitForExit(10000) -and -not $script:Proc.HasExited) { throw "Owned process did not stop after $Reason" }
}
function Read-TerminalMetrics {
    $Snapshot=[ordered]@{observed_utc=[DateTime]::UtcNow.ToString('o')}
    try {
        $Snapshot.C_free_bytes=Get-FreeBytes 'C'; $Snapshot.D_free_bytes=Get-FreeBytes 'D'
        $M=Get-Memory; $Snapshot.physical_free_bytes=[long]$M.physical; $Snapshot.commit_headroom_bytes=[long]$M.commit
        $script:MinC=[Math]::Min($script:MinC,[long]$Snapshot.C_free_bytes)
        $script:MinD=[Math]::Min($script:MinD,[long]$Snapshot.D_free_bytes)
        $script:MinPhysical=[Math]::Min($script:MinPhysical,[long]$Snapshot.physical_free_bytes)
        $script:MinCommit=[Math]::Min($script:MinCommit,[long]$Snapshot.commit_headroom_bytes)
    } catch { $Snapshot.telemetry_error=$_.Exception.Message }
    return $Snapshot
}
function Write-FailedStepReceipt([string]$StepId,[string]$Kind,[int]$ExitCode,[string]$StopReason,$TerminalMetrics) {
    $StepReceipt=[ordered]@{id=$StepId;kind=$Kind;status='FAILED';pid=$script:ProcId;created_utc=if($script:ProcStartUtc){$script:ProcStartUtc.ToString('o')}else{$null};observed_command_line=$script:CommandLine;exit_code=$ExitCode;stop_reason=$StopReason;terminal_metrics=$TerminalMetrics;minimum_physical_free_bytes=$script:MinPhysical;minimum_commit_headroom_bytes=$script:MinCommit;minimum_C_free_bytes=$script:MinC;minimum_D_free_bytes=$script:MinD}
    if ($script:OutPath -and (Test-Path -LiteralPath $script:OutPath -PathType Leaf)) { $StepReceipt.stdout=$script:OutPath; $StepReceipt.stdout_sha256=Hash-File $script:OutPath }
    if ($script:ErrPath -and (Test-Path -LiteralPath $script:ErrPath -PathType Leaf)) { $StepReceipt.stderr=$script:ErrPath; $StepReceipt.stderr_sha256=Hash-File $script:ErrPath }
    $script:StepReceipts+=,$StepReceipt
    $Receipt.failed_step=$StepId; $Receipt.stop_reason=$StopReason; $Receipt.terminal_metrics=$TerminalMetrics
    $Receipt.failed_step_exit_code=$ExitCode; $Receipt.steps=@($script:StepReceipts); $Receipt.status='FAILED'
    $Receipt.ended_utc=[DateTime]::UtcNow.ToString('o')
    try { $Receipt.total_output_bytes=Get-RunBytes $RunDir } catch { $Receipt.output_size_error=$_.Exception.Message }
    Write-JsonAtomic $ReceiptPath $Receipt
}

function Read-PngInfo([string]$Path) {
    $Stream=[IO.File]::OpenRead($Path)
    try {
        $Bytes=[byte[]]::new(24); $Offset=0
        while ($Offset -lt 24) { $Read=$Stream.Read($Bytes,$Offset,24-$Offset); if ($Read -le 0) { throw 'PNG header is truncated' }; $Offset += $Read }
    } finally { $Stream.Dispose() }
    $Signature=[byte[]]@(137,80,78,71,13,10,26,10)
    for ($i=0; $i -lt 8; $i++) { if ($Bytes[$i] -ne $Signature[$i]) { throw 'Capture output is not a PNG file' } }
    if ([Text.Encoding]::ASCII.GetString($Bytes,12,4) -cne 'IHDR') { throw 'PNG first chunk is not IHDR' }
    return @{width=[Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($Bytes,16));height=[Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($Bytes,20))}
}
function Get-CaptureResults($Step,[string]$GraphicsOverridePath) {
    $Dir=Split-Path -Parent ([string]$Step.expected_images[0].path)
    if (@(Get-ChildItem -LiteralPath $Dir -File).Count -ne 2 -or @(Get-ChildItem -LiteralPath $Dir -Directory).Count) { throw 'Exactly two fresh PNGs required per arm' }
    $Results=@()
    foreach ($ExpectedImage in $Step.expected_images) {
        $ImagePath=[string]$ExpectedImage.path
        if (-not (Test-Path -LiteralPath $ImagePath -PathType Leaf)) { throw "Expected capture PNG missing: $ImagePath" }
        $Info=Read-PngInfo $ImagePath
        if ([int]$Info.width -ne 1280 -or [int]$Info.height -ne 720) { throw "Capture dimensions mismatch: $ImagePath $($Info.width)x$($Info.height)" }
        $Results+=,[ordered]@{png=$ImagePath;sha256=(Hash-File $ImagePath);width=[int]$Info.width;height=[int]$Info.height;view=[string]$ExpectedImage.view;preset=[string]$Step.preset;arm=[string]$Step.arm;renderer='forward_plus';user_data_override=$GraphicsOverridePath;user_data_override_sha256=(Hash-File $GraphicsOverridePath)}
    }
    if ($Results.Count -ne @($Step.expected_images).Count -or $Results.Count -eq 0) { throw 'Capture output count differs from expected image set' }
    return ,$Results
}
function Run-Step($Step) {
    $script:CurrentStepId=[string]$Step.id; $script:ObservedStopReason=$null
    Assert-Source
    Assert-Hash $Engine $EngineSha
    Assert-Resources $true
    Assert-NoForeignEngine
    $StepId=[string]$Step.id; $HomeDir=Join-Path $RunDir ('h'+[array]::IndexOf($Job.steps,$Step))
    if ($StepId -notmatch '^[A-Za-z0-9-]+$') { throw 'Unsafe step id for isolated home path' }
    New-Item -ItemType Directory -Path $HomeDir | Out-Null
    $ProjectText=[IO.File]::ReadAllText((Join-Path $Stage 'project.godot'))
    $ProjectNameMatch=[regex]::Match($ProjectText,'(?m)^config/name="([^"]+)"\s*$')
    if (-not $ProjectNameMatch.Success -or $ProjectNameMatch.Groups[1].Value -cne [string]$Job.graphics_overrides.project_name) { throw 'Pinned project name does not match isolated user:// plan' }
    if ($ProjectText -match '(?m)^config/use_custom_user_dir\s*=\s*true\s*$') { throw 'Custom Godot user directory is unsupported by this isolated override plan' }
    $GraphicsText=[IO.File]::ReadAllText((Join-Path $Stage 'scripts/ui/graphics_prefs.gd'))
    if ($GraphicsText -notmatch '(?m)^const OVERRIDE_PATH := "user://graphics_override\.cfg"\s*$') { throw 'Pinned graphics preferences do not use the expected graphics_override.cfg path' }
    if ([string]$Job.graphics_overrides.user_data_path_rule -cne '%APPDATA%\Godot\app_userdata\Tetherbound\graphics_override.cfg') { throw 'Job user-data override path rule changed' }
    $Profile=$Job.graphics_overrides.profiles.PSObject.Properties[[string]$Step.preset].Value
    if ($null -eq $Profile) { throw "No pinned graphics profile for $($Step.preset)" }
    $UserDataDir=Join-Path (Join-Path (Join-Path $HomeDir 'Godot') 'app_userdata') ([string]$Job.graphics_overrides.project_name)
    New-Item -ItemType Directory -Path $UserDataDir -Force | Out-Null
    $script:GraphicsOverridePath=Join-Path $UserDataDir 'graphics_override.cfg'
    if (Test-Path -LiteralPath $script:GraphicsOverridePath) { throw 'Isolated graphics override unexpectedly exists before provisioning' }
    Assert-Hash ([string]$Profile.source) ([string]$Profile.sha256)
    $OverrideText=[IO.File]::ReadAllText([string]$Profile.source)
    if ($OverrideText -notmatch ('(?m)^preset="'+[regex]::Escape([string]$Step.preset)+'"\s*$') -or $OverrideText -notmatch '(?m)^renderer/rendering_method="forward_plus"\s*$') { throw 'Pinned graphics override does not match requested preset and renderer' }
    Copy-Item -LiteralPath ([string]$Profile.source) -Destination $script:GraphicsOverridePath
    Assert-Hash $script:GraphicsOverridePath ([string]$Profile.sha256)
    $OutPath=Join-Path $RunDir ($StepId+'.stdout.log'); $ErrPath=Join-Path $RunDir ($StepId+'.stderr.log')
    $script:OutPath=$OutPath; $script:ErrPath=$ErrPath
    $script:LogPaths+=@($OutPath,$ErrPath)
    $CaptureResult=$null
    $StepArgs=@($Step.args | ForEach-Object { [string]$_ })
    $StartInfo=[Diagnostics.ProcessStartInfo]::new(); $StartInfo.FileName=$Engine; $StartInfo.WorkingDirectory=$Stage
    $StartInfo.UseShellExecute=$false; $StartInfo.CreateNoWindow=$true; $StartInfo.WindowStyle=[Diagnostics.ProcessWindowStyle]::Hidden
    $StartInfo.RedirectStandardOutput=$true; $StartInfo.RedirectStandardError=$true
    foreach ($Arg in $StepArgs) { $StartInfo.ArgumentList.Add($Arg) }
    foreach ($Name in @('APPDATA','LOCALAPPDATA','XDG_CONFIG_HOME','XDG_DATA_HOME','XDG_CACHE_HOME','TEMP','TMP')) { $StartInfo.Environment[$Name]=$HomeDir }
    $Proc=[Diagnostics.Process]::new(); $Proc.StartInfo=$StartInfo
    Claim-Owner $StepId
    $Timer=[Diagnostics.Stopwatch]::StartNew()
    if (-not $Proc.Start()) { throw "Godot failed to start $StepId" }
    $script:Proc=$Proc
    $script:ProcId=$Proc.Id; $script:ProcStartUtc=$Proc.StartTime.ToUniversalTime()
    Record-OwnedChild $script:ProcId $script:ProcStartUtc $StepId
    $OutStream=[IO.File]::Open($OutPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
    $script:OutStream=$OutStream
    $ErrStream=[IO.File]::Open($ErrPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
    $script:ErrStream=$ErrStream
    $OutTask=$Proc.StandardOutput.BaseStream.CopyToAsync($OutStream); $ErrTask=$Proc.StandardError.BaseStream.CopyToAsync($ErrStream)
    $script:OutTask=$OutTask; $script:ErrTask=$ErrTask
    $Initial=$null
    for ($Try=0; $Try -lt 20 -and -not $Initial; $Try++) {
        if ($Proc.HasExited) { break }
        $Rows=@(Get-CimInstance Win32_Process -Filter "ProcessId = $script:ProcId" -ErrorAction SilentlyContinue)
        if ($Rows.Count -eq 1 -and -not [string]::IsNullOrWhiteSpace([string]$Rows[0].ExecutablePath) -and -not [string]::IsNullOrWhiteSpace([string]$Rows[0].CommandLine) -and $Rows[0].CreationDate) { $Initial=$Rows[0] } else { Start-Sleep -Milliseconds 100 }
    }
    if (-not $Initial) { Stop-OwnedProcess 'initial CIM readiness failed'; throw 'No complete initial CIM identity before startup timeout/exit' }
    $ObservedCommand=[string]$Initial.CommandLine
    $ExpectedSuffix=$StepArgs -join ' '
    $QuotedPrefix='"'+$Engine+'" '
    $PlainPrefix=$Engine+' '
    $ArgvMatches=($ObservedCommand.StartsWith($QuotedPrefix,[StringComparison]::Ordinal) -and $ObservedCommand.Substring($QuotedPrefix.Length) -ceq $ExpectedSuffix) -or ($ObservedCommand.StartsWith($PlainPrefix,[StringComparison]::Ordinal) -and $ObservedCommand.Substring($PlainPrefix.Length) -ceq $ExpectedSuffix)
    if ([int]$Initial.ParentProcessId -ne $script:RunnerPid -or [IO.Path]::GetFullPath([string]$Initial.ExecutablePath) -cne [IO.Path]::GetFullPath($Engine) -or -not $ArgvMatches) { Stop-OwnedProcess 'identity or argv verification failed'; throw 'Initial process parent, image or exact argv differs from job' }
    $InitTime=if ($Initial.CreationDate -is [DateTime]) {$Initial.CreationDate.ToUniversalTime()} else {[Management.ManagementDateTimeConverter]::ToDateTime([string]$Initial.CreationDate).ToUniversalTime()}
    if ([Math]::Abs(($InitTime-$script:ProcStartUtc).TotalSeconds) -gt 1.0) { Stop-OwnedProcess 'creation-time verification failed'; throw 'Initial CIM creation time differs from owned process handle' }
    $script:CommandLine=[string]$Initial.CommandLine
    $Before=Assert-Resources
    $StopReason=$null
    while (-not $Proc.HasExited) {
        try {
            Assert-Resources
            Assert-NoForeignEngine $script:ProcId
            $null=Assert-OwnedCim
            if ($Timer.Elapsed.TotalSeconds -ge [int]$Step.wall_seconds) { $StopReason='wall-clock cap reached'; break }
            $OutStream.Flush(); $ErrStream.Flush()
            $ActualLogBytes=Get-CombinedLogBytes
            if ($ActualLogBytes -gt $CombinedLogsCap) { $StopReason='stdout/stderr cap reached'; break }
            if ((Get-RunBytes $RunDir) -gt $OutputCap) { $StopReason='output/home cap reached'; break }
      } catch { $StopReason=$_.Exception.Message; $script:ObservedStopReason=$StopReason; break }
        Start-Sleep -Milliseconds 1000
    }
    if ($StopReason) { $script:ObservedStopReason=[string]$StopReason }
    if ($StopReason) { Stop-OwnedProcess $StopReason }
    if (-not $Proc.HasExited) { throw 'Owned process remained live after stop path' }
    $Proc.WaitForExit()
    $null=$OutTask.GetAwaiter().GetResult(); $null=$ErrTask.GetAwaiter().GetResult()
    $OutStream.Dispose(); $ErrStream.Dispose(); $script:OutStream=$null; $script:ErrStream=$null; $script:OutTask=$null; $script:ErrTask=$null
    $Exit=[int]$Proc.ExitCode
    $TerminalMetrics=Read-TerminalMetrics
    if ($Exit -ne 0 -or $StopReason) {
        $FailedReason=if($StopReason){[string]$StopReason}else{"process exited with code $Exit; stop cause not observed"}
        Write-FailedStepReceipt $StepId ([string]$Step.kind) $Exit $FailedReason $TerminalMetrics
        throw "Godot step $StepId failed: $FailedReason"
    }
    if ((Get-CombinedLogBytes) -gt $CombinedLogsCap) { throw 'Combined stdout/stderr exceeded cap after exit' }
    if ((Get-RunBytes $RunDir) -gt $OutputCap) { throw 'Run output exceeded cap after exit' }
    $Stdout=[IO.File]::ReadAllText($OutPath); $Stderr=[IO.File]::ReadAllText($ErrPath)
    if (-not [string]::IsNullOrWhiteSpace($Stderr)) { throw "Hall capture stderr must be empty" }
    if (($Stdout+([Environment]::NewLine)+$Stderr) -match '(?i)velocity.{0,100}exceeded.{0,40}ceiling|falling trainer') { throw 'Diagnostic trainer velocity/fall warning found in process logs' }
    if (($Stdout+"`n"+$Stderr) -match '(?im)SCRIPT ERROR|Parse Error:|^(WARNING|ERROR):|missing asset') { throw "Godot step $StepId emitted script/engine errors" }
    if ($Step.kind -eq 'parser') {
        if (-not [string]::IsNullOrWhiteSpace($Stderr)) { throw 'Parser stderr must be empty' }
    } elseif ($Step.kind -eq 'tests') {
        $ExpectedTests=[int]$Step.expected_test_methods
        $Summary=[regex]::Match($Stdout,'(?m)^(\d+) tests, (\d+) assertions, (\d+) failed\r?$')
        if (-not $Summary.Success -or [int]$Summary.Groups[1].Value -ne $ExpectedTests -or [int]$Summary.Groups[2].Value -le 0 -or [int]$Summary.Groups[3].Value -ne 0) { throw "Test totals mismatch for $StepId" }
        if ($Stdout -notmatch [regex]::Escape([string]$Step.expected_selector_summary)) { throw "Test selector summary missing for $StepId" }
    } else {
        foreach ($Marker in $Step.required_output_markers) { if ($Stdout -notmatch [regex]::Escape([string]$Marker)) { throw "Required Hall night capture output marker missing for $StepId" } }
        $GodotLogs=@(Get-ChildItem -LiteralPath $HomeDir -File -Force -Recurse | Where-Object { $_.Name -eq 'godot.log' })
        foreach ($Log in $GodotLogs) { $LogText=[IO.File]::ReadAllText($Log.FullName); if ($LogText -match '(?i)velocity.{0,100}exceeded.{0,40}ceiling|falling trainer') { throw "Diagnostic trainer velocity/fall warning found in $($Log.FullName)" } }
    }
    if ($Step.kind -eq 'capture') {
        $CaptureResult=Get-CaptureResults $Step $script:GraphicsOverridePath
    }
    $Live=@(Get-CimInstance Win32_Process -Filter "ProcessId = $script:ProcId" -ErrorAction SilentlyContinue)
    if ($Live.Count -gt 0) { throw 'Godot process remains present after exit' }
    Assert-NoForeignEngine
    $StepReceipt=[ordered]@{id=$StepId;kind=$Step.kind;status='PASSED';pid=$script:ProcId;created_utc=$script:ProcStartUtc.ToString('o');observed_command_line=$script:CommandLine;expected_arguments=$StepArgs;exit_code=$Exit;stop_reason=$null;terminal_metrics=$TerminalMetrics;wall_seconds=[Math]::Round($Timer.Elapsed.TotalSeconds,3);capture=$CaptureResult;stdout=$OutPath;stdout_sha256=(Hash-File $OutPath);stderr=$ErrPath;stderr_sha256=(Hash-File $ErrPath);stdout_stderr_bytes=([long](Get-Item $OutPath).Length+[long](Get-Item $ErrPath).Length);preflight_memory=$Before;minimum_physical_free_bytes=$script:MinPhysical;minimum_commit_headroom_bytes=$script:MinCommit;minimum_C_free_bytes=$script:MinC;minimum_D_free_bytes=$script:MinD}
    $script:StepReceipts+=,$StepReceipt
    Update-Owner $true $script:ProcId $StepId; $script:LeaseOwned=$false; $script:LeaseRun=$null; $script:LeasePid=0
    $Proc.Dispose(); $script:Proc=$null; $script:ProcId=$null; $script:ProcStartUtc=$null; $script:CommandLine=$null
}


$Job=Read-Json $JobPath; $Admission=Read-Json $AdmissionPath
if ($Job.schema -cne 'codex.visual-hall-night-native-run.v1' -or $Job.job_id -cne 'hallcontacted-r1' -or $Job.source_commit -cne $ExpectedSource -or $Job.supervisor_sha256 -cne (Hash-File $PSCommandPath) -or $Admission.job_sha256 -cne (Hash-File $JobPath)) { throw 'Exact source/job/supervisor admission binding required' }
Assert-Hash $Job.manifest_binding.path $Job.manifest_binding.sha256
Assert-Hash $Job.pack_binding.path $Job.pack_binding.sha256
Assert-Hash $Job.pack_binding.preflight_path $Job.pack_binding.preflight_sha256
$Manifest=Read-Json $Job.manifest_binding.path
if ($Manifest.source -cne $ExpectedSource -or $Job.source_bindings.Count -ne 15 -or $Job.steps.Count -ne 2 -or (($Job.steps | ForEach-Object id) -join ',') -cne 'frame-Medium-diagnostic,frame-no-night-floor-Medium-diagnostic') { throw 'Exact two-arm diagnostic required' }
for($i=0;$i -lt 2;$i++) {
    $S=$Job.steps[$i]; $C=$Manifest.commands[$i]
    $Dest=([string]$Job.output_directory).Replace('\','/')+'/images/'+[string]$S.id
    $ExpectedArgs=@($C.args | ForEach-Object { if($_ -like '--out=*') {'--out='+$Dest} else {[string]$_} })
    if (($S.args -join "`n") -cne ($ExpectedArgs -join "`n") -or $S.kind -cne 'capture' -or $S.preset -cne 'Medium' -or $S.arm -cne $C.arm -or $S.wall_seconds -ne 120 -or $S.expected_images.Count -ne 2) { throw 'Exact bounded capture arguments differ' }
    for($v=0;$v -lt 2;$v++) {
        $Name=[IO.Path]::GetFileName([string]$C.expected_images[$v]); $Image=$S.expected_images[$v]
        if ([IO.Path]::GetFullPath([string]$Image.path) -cne [IO.Path]::GetFullPath(($Dest+'/'+$Name)) -or $Image.view -cne [IO.Path]::GetFileNameWithoutExtension($Name)) { throw 'Expected image path/view differs' }
    }
}
if ($Job.engine.path -cne $Engine -or $Job.engine.sha256 -cne $EngineSha) { throw 'Engine pin differs' }
Assert-Hash $Engine $EngineSha
foreach($Profile in $Job.graphics_overrides.profiles.PSObject.Properties.Value) { Assert-Hash $Profile.source $Profile.sha256 }
if ([long]$Job.caps.C_admission_bytes -ne $CAdmissionFloor -or [long]$Job.caps.C_stop_bytes -ne $CStopFloor -or [long]$Job.caps.D_admission_bytes -ne $DAdmissionFloor -or [long]$Job.caps.D_stop_bytes -ne $DStopFloor -or [long]$Job.caps.combined_stdout_stderr_bytes -ne $CombinedLogsCap -or [long]$Job.caps.run_output_and_isolated_homes_bytes -ne $OutputCap -or [long]$Job.caps.physical_and_commit_bytes -ne $MemoryFloor -or [long]$Job.caps.packet_bytes -ne $PacketCap) { throw 'Resource caps differ' }
if ($CpuStagePreflightFixture -or $CpuPacketFixture) {
    if ($Job.status -cne 'PREPARED' -or $Job.launch_allowed -ne $false -or $Admission.status -cne 'NOT_ADMITTED' -or $Admission.launch_allowed -ne $false) { throw 'CPU mode requires NOT_ADMITTED packet' }
    if($CpuStagePreflightFixture) { Assert-Source }
    'CPU Hall night packet validation PASS; no engine launch.'; exit 0
}
if ($Job.status -cne 'ROOT_ADMITTED' -or $Job.launch_allowed -ne $true -or $Admission.status -cne 'ROOT_ADMITTED' -or $Admission.launch_allowed -ne $true -or $Admission.reviewed_by_thread -cne $ExpectedThread) { throw 'Explicit root admission required' }
Assert-Source
Assert-Resources $true
Assert-NoForeignEngine
if ((Get-RunBytes $ArtifactDir) -gt $PacketCap) { throw 'Packet exceeds16MiB' }
$RunDir=[string]$Job.output_directory
$ExpectedRunDir=Join-Path $OutputRoot ('run-'+$Job.job_id)
if ([IO.Path]::GetFullPath($RunDir) -cne [IO.Path]::GetFullPath($ExpectedRunDir) -or (Test-Path -LiteralPath $RunDir)) { throw 'Output directory must be the declared fresh path' }
if (-not (Test-Path -LiteralPath $OwnerLockPath -PathType Leaf)) { throw 'Native owner lock file missing' }
$script:OwnerLock=[IO.File]::Open($OwnerLockPath,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
$Owner=Read-Owner
if ($Owner.thread -cne $ExpectedThread -or $Owner.reserved -ne $true -or $Owner.allow_native_launch -ne $true -or $Owner.active_process_id -or $Owner.active_session_id -or $Owner.run_id -or @($Owner.processes).Count -gt 0) { throw 'Exact native lease is not idle/reserved' }
Assert-NoForeignEngine; Assert-Resources $true
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $RunDir) | Out-Null
New-Item -ItemType Directory -Path $RunDir | Out-Null
$ReceiptPath=Join-Path $RunDir 'receipt.json'
$Receipt=[ordered]@{status='RUNNING';job_id=$Job.job_id;source_commit=$ExpectedSource;engine_sha256=$EngineSha;started_utc=[DateTime]::UtcNow.ToString('o');capture_manifest=$Job.manifest_binding;steps=@();limits=@{C_admission_bytes=$CAdmissionFloor;C_stop_bytes=$CStopFloor;D_admission_bytes=$DAdmissionFloor;D_stop_bytes=$DStopFloor;memory_floor_bytes=$MemoryFloor;combined_logs_bytes=$CombinedLogsCap;output_bytes=$OutputCap}}
Write-JsonAtomic $ReceiptPath $Receipt
try {
    foreach ($Step in $Job.steps) {
        Run-Step $Step
        $Receipt.steps=@($script:StepReceipts); Write-JsonAtomic $ReceiptPath $Receipt
    }
    $Receipt.status='EXITED_ZERO_AWAITING_REVIEW'; $Receipt.ended_utc=[DateTime]::UtcNow.ToString('o'); $Receipt.total_output_bytes=Get-RunBytes $RunDir
    Write-JsonAtomic $ReceiptPath $Receipt
} catch {
    if ($script:CurrentStepId -and -not $Receipt.failed_step) {
        try {
            $FailExit=if($script:Proc -and $script:Proc.HasExited){[int]$script:Proc.ExitCode}else{-1}
            $FailReason=if($script:ObservedStopReason){[string]$script:ObservedStopReason}else{$_.Exception.Message}
            Write-FailedStepReceipt $script:CurrentStepId 'unknown' $FailExit $FailReason (Read-TerminalMetrics)
        } catch { $Receipt.failed_step=$script:CurrentStepId; $Receipt.stop_reason=$_.Exception.Message }
    }
    $Receipt.status='FAILED'; $Receipt.failure=$_.Exception.Message; $Receipt.ended_utc=[DateTime]::UtcNow.ToString('o'); $Receipt.steps=@($script:StepReceipts)
    try { $Receipt.total_output_bytes=Get-RunBytes $RunDir; Write-JsonAtomic $ReceiptPath $Receipt } catch {}
    throw
} finally {
    if ($script:Proc -and -not $script:Proc.HasExited) {
        try { Stop-OwnedProcess 'failure cleanup'; $script:Proc.WaitForExit(10000) | Out-Null } catch { $Receipt.cleanup_blocked=$_.Exception.Message }
    }
    if ($script:LeaseOwned -and ((-not $script:Proc) -or $script:Proc.HasExited)) {
        try { Assert-NoForeignEngine; Update-Owner $true $script:LeasePid $script:LeaseRun; $script:LeaseOwned=$false } catch { $Receipt.cleanup_blocked=$_.Exception.Message; try { Write-JsonAtomic $ReceiptPath $Receipt } catch {} }
    }
    if ($script:LeaseOwned) { $Receipt.lease_retained_for_live_or_unverified_child=$true; try { Write-JsonAtomic $ReceiptPath $Receipt } catch {} }
    if ($script:Proc -and $script:Proc.HasExited) {
        try { $script:Proc.WaitForExit(); if ($script:OutTask) { $null=$script:OutTask.GetAwaiter().GetResult() }; if ($script:ErrTask) { $null=$script:ErrTask.GetAwaiter().GetResult() } } catch {}
    }
    if ($script:OutStream) { $script:OutStream.Dispose() }; if ($script:ErrStream) { $script:ErrStream.Dispose() }
    if ($script:Proc) { $script:Proc.Dispose() }
    if ($script:OwnerLock) { $script:OwnerLock.Dispose() }
}

extends SceneTree

## Fixed-camera capture for one visual item (WORKFLOW 8.1 rule 10): boots the
## Meadows, stands the trainer at each view's `player` point (the 1.80 m
## ruler), puts a free camera at `pos` looking at `look_at` (or by
## yaw/pitch), sets WorldLook's named time and WorldWeather's preset, and
## saves <out>/<view id>.png. The same set gives the same cameras every round,
## unlike a walk whose stops drift with frame timing. HUD hidden; the
## companion stays recalled (its clearance is covered by the follower tests).
##
##   xvfb-run godot --path . --rendering-driver opengl3 --resolution 1920x1080 \
##     --script res://tools/visual_judge/capture_camera_set.gd -- \
##     --set=res://tools/visual_judge/camera_sets/F17-6.json --out=/abs/dir

const SCENE := "res://scenes/world/meadows_playground.tscn"
const SETTLE_FRAMES := 12
const RAIN_SETTLE_FRAMES := 16
const GRAPHICS := preload("res://scripts/ui/graphics_prefs.gd")
var _hall_prefabs: RefCounted


func _init() -> void:
	_run.call_deferred()


func _run() -> void:
	var set_path := ""
	var out := ""
	var expected_preset := ""
	var selected_views: PackedStringArray = []
	var hall_ground_y := NAN
	var hall_arm := "baseline"
	for a: String in OS.get_cmdline_user_args():
		if a.begins_with("--set="):
			set_path = a.trim_prefix("--set=")
		elif a.begins_with("--out="):
			out = a.trim_prefix("--out=")
		elif a.begins_with("--preset="):
			expected_preset = a.trim_prefix("--preset=")
		elif a.begins_with("--views="):
			selected_views = a.trim_prefix("--views=").split(",", false)
		elif a.begins_with("--hall-only-ground-y="):
			hall_ground_y = float(a.trim_prefix("--hall-only-ground-y="))
		elif a.begins_with("--hall-arm="):
			hall_arm = a.trim_prefix("--hall-arm=")
	if hall_arm not in ["baseline", "furnishing", "frame", "frame-no-night-floor"] or (hall_arm != "baseline" and is_nan(hall_ground_y)):
		push_error("CAMERA_SET --hall-arm must be baseline/furnishing/frame/frame-no-night-floor; candidates require isolated Hall")
		quit(2)
		return
	var camera_set: Variant = JSON.parse_string(FileAccess.get_file_as_string(set_path))
	if not camera_set is Dictionary or out == "":
		push_error("capture_camera_set: needs --set=<camera set json> and --out=<dir>")
		quit(2)
		return
	var contact: Dictionary = camera_set.get("contact_fixture", {})
	if not contact.is_empty():
		if not is_equal_approx(float(contact.get("idle_sample_seconds", -1.0)), 0.2):
			push_error("CAMERA_SET contact fixture requires the measured idle sample")
			quit(2)
			return
		if is_nan(hall_ground_y) or not is_equal_approx(hall_ground_y, float(contact["required_ground_y"])):
			push_error("CAMERA_SET contact fixture requires its measured isolated Hall ground height")
			quit(2)
			return
		for path: String in contact.get("source_hashes", {}):
			var digest := FileAccess.get_sha256(path) if path.ends_with(".glb") or path.ends_with(".bin") \
				else FileAccess.get_file_as_string(path).replace("\r\n", "\n").sha256_text()
			if digest != str(contact["source_hashes"][path]):
				push_error("CAMERA_SET contact fixture source changed; remeasure " + path)
				quit(2)
				return
		for view: Dictionary in camera_set.get("views", []):
			if not is_equal_approx(float(view["player"][1]), float(contact["player_y"])):
				push_error("CAMERA_SET contact fixture has an unmeasured trainer stand")
				quit(2)
				return
		print("CAMERA_SET fixture=%s floor_y=%s idle_sole_offset=%s; fresh paired recapture required" % [
			str(camera_set.get("fixture_version", "")), str(contact["rendered_floor_y"]), str(contact["idle_sole_offset_m"])])
	if DirAccess.make_dir_recursive_absolute(out) != OK:
		push_error("capture_camera_set: cannot create output directory")
		quit(2)
		return
	if not expected_preset.is_empty() and (GRAPHICS.selected() != expected_preset or GRAPHICS.restart_required()):
		push_error("capture_camera_set: actual preset/renderer does not match --preset=" + expected_preset)
		quit(2)
		return
	print("CAMERA_SET graphics: %s / %s" % [GRAPHICS.selected(), RenderingServer.get_current_rendering_method()])
	var views: Array = []
	for view: Dictionary in camera_set.get("views", []):
		if selected_views.is_empty() or str(view.get("id", "")) in selected_views:
			views.append(view)
	if views.is_empty() or (not selected_views.is_empty() and views.size() != selected_views.size()):
		push_error("capture_camera_set: empty set or unknown/duplicate --views selection")
		quit(2)
		return
	var world := (load(SCENE) as PackedScene).instantiate() as Node3D
	if not is_nan(hall_ground_y):
		for view: Dictionary in views:
			if not str(view.id).begins_with("nave-") and not str(view.id).begins_with("shrine-"):
				push_error("Hall-only diagnostic forbids exterior views")
				world.free()
				quit(2)
				return
		# Keep authored light/environment and the actual trainer rig, but never
		# enter the Meadows world builder or its terrain/placement systems.
		world.set_script(null)
		for child: Node in world.get_children():
			if str(child.name) not in ["Sun", "WorldEnvironment", "WorldLook", "WorldWeather", "Player"]:
				world.remove_child(child)
				child.free()
		var isolated_player := world.get_node_or_null(^"Player")
		if isolated_player != null:
			isolated_player.set_physics_process(false)
	root.add_child(world)
	current_scene = world
	# _ready runs during add_child and can re-enable authored processing.
	# Freeze only afterwards, before any physics-frame settling is allowed.
	if not _hold_capture_trainer(world, views[0]):
		quit(2)
		return
	if not contact.is_empty():
		var contact_model := world.get_node(^"Player/Model") as Node3D
		if str(contact_model.get("_config_key")) != str(contact["appearance"]) \
				or absf(contact_model.position.y) > 0.00001 \
				or not is_equal_approx(float(contact_model.call("height")), 1.8) \
				or str(contact_model.call("clip_for", "idle", "idle")) != "idle":
			push_error("CAMERA_SET contact fixture appearance/model offset differs from measured rig")
			quit(2)
			return
	if not is_nan(hall_ground_y) and not _mount_isolated_hall(world, hall_ground_y, hall_arm):
		quit(2)
		return
	for i in 300:
		await physics_frame
	if not get_nodes_in_group(&"deployed_creature").is_empty():
		push_error("capture_camera_set: companion must be recalled in the isolated capture state")
		quit(2)
		return
	var hud := world.get_node_or_null(^"PlaygroundHUD")
	if hud != null:
		hud.set("visible", false)
	var look := world.get_node_or_null(^"WorldLook")
	var weather := world.get_node_or_null(^"WorldWeather")
	if look == null or weather == null:
		push_error("capture_camera_set: WorldLook and WorldWeather are required")
		quit(2)
		return
	if look != null:
		look.call("set_clock_frozen", true)
	var player := world.get_node_or_null(^"Player") as Node3D
	if player == null:
		push_error("capture_camera_set: fixed trainer ruler is missing")
		quit(2)
		return
	# A fixed composition must not let gravity/input move the ruler while
	# render frames settle. This diagnostic does not prove traversal.
	player.set_physics_process(false)
	var cam := Camera3D.new()
	root.add_child(cam)
	GRAPHICS.apply_camera(cam)
	var saved := 0
	for raw: Variant in views:
		var view: Dictionary = raw
		if player != null and view.get("player") is Array:
			var p: Array = view["player"]
			player.global_position = Vector3(float(p[0]), float(p[1]), float(p[2]))
			if player is CharacterBody3D:
				(player as CharacterBody3D).velocity = Vector3.ZERO
		var pos: Array = view.get("pos", [0, 0, 0])
		var eye := Vector3(float(pos[0]), float(pos[1]), float(pos[2]))
		cam.fov = float(view.get("fov", 70.0))
		if view.get("look_at") is Array:
			var t: Array = view["look_at"]
			cam.global_transform = Transform3D(Basis(), eye).looking_at(
				Vector3(float(t[0]), float(t[1]), float(t[2])), Vector3.UP)
		else:
			cam.global_transform = Transform3D(Basis.from_euler(Vector3(
				deg_to_rad(float(view.get("pitch", 0.0))), deg_to_rad(float(view.get("yaw", 0.0))), 0.0)), eye)
		cam.current = true
		if player != null and view.get("player") is Array:
			# Trainer faces away from the camera, as the follow camera shows them.
			var away := player.global_position - eye
			player.global_rotation.y = atan2(away.x, away.z)
		var weather_name := str(view.get("weather", "clear"))
		if weather != null:
			weather.call("set_weather", weather_name)
		if look != null:
			look.call("apply_time", str(view.get("time_name", "day")))
		for f in (RAIN_SETTLE_FRAMES if weather_name == "rain" else SETTLE_FRAMES):
			await process_frame
		await RenderingServer.frame_post_draw
		var image := root.get_viewport().get_texture().get_image()
		var file := out.path_join("%s.png" % str(view.get("id", "view")))
		if image != null and not image.is_empty() and image.save_png(file) == OK:
			saved += 1
			print("CAMERA_SET %s saved" % str(view.get("id", "")))
		else:
			push_error("CAMERA_SET image save failed: " + file)
	print("CAMERA_SET done: %d views" % saved)
	quit(0 if saved == views.size() else 2)


func _hold_capture_trainer(world: Node3D, first_view: Dictionary) -> bool:
	var trainer := world.get_node_or_null(^"Player") as CharacterBody3D
	if trainer == null or not first_view.get("player") is Array:
		push_error("CAMERA_SET fixed trainer stand is required")
		return false
	trainer.set_physics_process(false)
	trainer.velocity = Vector3.ZERO
	var stand: Array = first_view["player"]
	trainer.global_position = Vector3(float(stand[0]), float(stand[1]), float(stand[2]))
	var model := trainer.get_node_or_null(^"Model")
	if model == null or not model.has_method("clip_for") or not model.has_method("animation_player"):
		push_error("CAMERA_SET production trainer animation path missing")
		return false
	# With no simulated floor, the normal state selector chooses jump. Use
	# its production idle mapping/play path, then hold one disclosed sample.
	# Do not modify the rig, character scale, clip resource or stand position.
	model.set_physics_process(false)
	var clip := str(model.call("clip_for", "idle", "idle"))
	var animation := model.call("animation_player") as AnimationPlayer
	if animation == null or not animation.has_animation(clip):
		push_error("CAMERA_SET production idle animation missing: " + clip)
		return false
	model.call("play", clip, true)
	animation.advance(0.2)
	animation.pause()
	print("CAMERA_SET trainer held after ready at %s; production idle=%s sample=0.2s" % [trainer.global_position, clip])
	return true


func _mount_isolated_hall(world: Node3D, ground_y: float, arm: String) -> bool:
	_hall_prefabs = load("res://scripts/world/building_prefabs.gd").new()
	var templates := Node3D.new()
	templates.name = "HallTemplates"
	templates.visible = false
	world.add_child(templates)
	_hall_prefabs.call("set_template_holder", templates)
	if not bool(_hall_prefabs.call("load_recipes")):
		return false
	var building := _hall_prefabs.call("instantiate", "crossing_hall_shell") as Node3D
	if building == null:
		return false
	world.add_child(building)
	# Authored village.json placement, with explicitly disclosed ground Y;
	# no synthetic terrain is presented as the real Meadows environment.
	building.position = Vector3(107.0, ground_y - 0.05, 14.0)
	building.rotation.y = deg_to_rad(90.0)
	var hall := load("res://scripts/world/crossing_hall.gd").new() as Node3D
	building.add_child(hall)
	var cfg: Variant = JSON.parse_string(FileAccess.get_file_as_string("res://data/config/crossing_hall.json"))
	if not cfg is Dictionary or bool(cfg.get("hall_furnishing", {}).get("enabled", false)) or bool(cfg.get("hall_timber_frame", {}).get("enabled", false)):
		push_error("Hall diagnostic requires both production candidate flags OFF")
		return false
	# This private copy dies with the diagnostic process; never write config.
	# frame compares against furnishing with identical furnishing on both sides.
	var selected: Dictionary = cfg.duplicate(true)
	selected["hall_furnishing"]["enabled"] = arm != "baseline"
	selected["hall_timber_frame"]["enabled"] = arm in ["frame", "frame-no-night-floor"]
	# Hall III hit the two-flat-round limit for structural changes. This
	# separate diagnostic tests only the Compatibility-era warm emission
	# floor. No production config write, ambient/fog/light or geometry edit.
	if arm == "frame-no-night-floor":
		var ambient: Dictionary = selected.get("interior_ambient", {})
		if not ambient.has("night_floor_energy") or not ambient.has("sealed_night_floor_energy"):
			push_error("Hall night-floor diagnostic requires explicit baseline energies")
			return false
		print("CAMERA_SET night-floor diagnostic: shell=%s sealed=%s -> 0; other settings unchanged" % [
			str(ambient["night_floor_energy"]), str(ambient["sealed_night_floor_energy"])])
		ambient["night_floor_energy"] = 0.0
		ambient["sealed_night_floor_energy"] = 0.0
		selected["interior_ambient"] = ambient
	print("CAMERA_SET Hall arm=%s; production flags OFF; process-local selection only" % arm)
	print("CAMERA_SET ISOLATED HALL DIAGNOSTIC ground_y=%s; no terrain/traversal/world acceptance" % ground_y)
	return bool(hall.call("build", selected))

extends RefCounted

## F26 prototype. Device-local presentation only; never a character/world
## mutation, RPC or combat input. project.godot points its preboot override at
## OVERRIDE_PATH. Compatibility remains the authored default (RD-25).
const CONFIG_PATH := "res://data/config/art.json"
const OVERRIDE_PATH := "user://graphics_override.cfg"
const PRESETS: Array[String] = ["Low", "Medium", "High"]
const FEATURES: Array[String] = ["volumetric_fog", "ssao", "ssil", "glow"]

static var _loaded := false
static var _config: Dictionary = {}
static var _choice := "Low"
static var _base := "Low"
static var _custom: Dictionary = {}
static var _overlay := false
static var _applied_shadow_profile := ""


static func load_preferences() -> void:
	if _loaded:
		return
	_loaded = true
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(CONFIG_PATH))
	if parsed is Dictionary and parsed.get("graphics_presets") is Dictionary:
		_config = parsed["graphics_presets"].duplicate(true)
	var stored := ConfigFile.new()
	if stored.load(OVERRIDE_PATH) != OK or not _usable_document(stored):
		# A refused promotion/rollback retains the previous generation. Startup
		# conservatively chose Low if the canonical file was absent; retaining
		# the device choice here allows an explicit restart after recovery.
		if stored.load(OVERRIDE_PATH + ".previous") != OK or not _usable_document(stored):
			return
	var selected := str(stored.get_value("tetherbound_graphics", "preset", "Low"))
	var base := str(stored.get_value("tetherbound_graphics", "base", "Low"))
	if not PRESETS.has(base) or not (PRESETS.has(selected) or selected == "Custom"):
		return
	_base = base
	_choice = selected
	var overrides: Variant = stored.get_value("tetherbound_graphics", "custom", {})
	_custom = overrides.duplicate(true) if overrides is Dictionary else {}
	_overlay = bool(stored.get_value("tetherbound_graphics", "overlay", false))


static func selected() -> String:
	load_preferences()
	return _choice


static func forward_plus() -> bool:
	return RenderingServer.get_current_rendering_method() == "forward_plus"


static func requested_renderer() -> String:
	load_preferences()
	return "gl_compatibility" if _base == "Low" else "forward_plus"


static func restart_required() -> bool:
	return requested_renderer() != RenderingServer.get_current_rendering_method()


static func values() -> Dictionary:
	load_preferences()
	var authored: Variant = _config.get(_base, {})
	var out: Dictionary = authored.duplicate(true) if authored is Dictionary else {}
	if _choice == "Custom":
		for key: String in FEATURES:
			if _custom.get(key) is bool:
				out[key] = _custom[key]
		for key: String in ["shadow_quality", "draw_distance"]:
			var options: Variant = _config.get(key + "_options", {})
			if options is Dictionary and options.has(_custom.get(key)):
				out[key] = _custom[key]
	# A selected Medium awaiting restart, or a driver fallback to OpenGL, must
	# never enable unsupported features on the renderer actually running.
	if not forward_plus():
		for key: String in FEATURES:
			out[key] = false
	return out


static func choose(preset: String) -> Error:
	load_preferences()
	if not PRESETS.has(preset):
		return ERR_INVALID_PARAMETER
	return _commit(preset, preset, {}, _overlay)


static func customize(key: String, value: Variant) -> Error:
	load_preferences()
	if FEATURES.has(key):
		if not (value is bool) or _base == "Low" or not forward_plus():
			return ERR_INVALID_PARAMETER
	elif key == "shadow_quality" or key == "draw_distance":
		var options: Variant = _config.get(key + "_options", {})
		if not (options is Dictionary) or not options.has(value):
			return ERR_INVALID_PARAMETER
	else:
		return ERR_INVALID_PARAMETER
	var custom := _custom.duplicate(true)
	custom[key] = value
	return _commit("Custom", _base, custom, _overlay)


static func set_overlay(enabled: bool) -> Error:
	load_preferences()
	return _commit("Custom", _base, _custom, enabled)


static func overlay_enabled() -> bool:
	load_preferences()
	return _overlay


static func _commit(choice: String, base: String, custom: Dictionary, overlay: bool) -> Error:
	# One device document holds preferences and preboot renderer choice. A
	# failed write leaves the in-memory choice unchanged and reports to the UI.
	var doc := ConfigFile.new()
	doc.set_value("tetherbound_graphics", "preset", choice)
	doc.set_value("tetherbound_graphics", "base", base)
	doc.set_value("tetherbound_graphics", "custom", custom)
	doc.set_value("tetherbound_graphics", "overlay", overlay)
	doc.set_value("rendering", "renderer/rendering_method", "gl_compatibility" if base == "Low" else "forward_plus")
	var error := _persist_document(doc)
	if error != OK:
		return error
	_choice = choice
	_base = base
	_custom = custom.duplicate(true)
	_overlay = overlay
	return OK


static func _usable_document(doc: ConfigFile) -> bool:
	var base := str(doc.get_value("tetherbound_graphics", "base", ""))
	var choice := str(doc.get_value("tetherbound_graphics", "preset", ""))
	return PRESETS.has(base) and (PRESETS.has(choice) or choice == "Custom") \
		and (choice == "Custom" or choice == base) \
		and doc.get_value("tetherbound_graphics", "custom", null) is Dictionary \
		and doc.get_value("tetherbound_graphics", "overlay", null) is bool \
		and str(doc.get_value("rendering", "renderer/rendering_method", "")) == ("gl_compatibility" if base == "Low" else "forward_plus")


static func _persist_document(doc: ConfigFile) -> Error:
	# ConfigFile.save cannot confirm buffered/flush success. Stage and verify
	# bytes first; preserve the prior document until promotion succeeds.
	# This is a per-device file transaction, not an OS power-loss guarantee.
	var bytes := doc.encode_to_text().to_utf8_buffer()
	var temporary := OVERRIDE_PATH + ".pending-" + Crypto.new().generate_random_bytes(16).hex_encode()
	var file := FileAccess.open(temporary, FileAccess.WRITE)
	if file == null:
		return ERR_FILE_CANT_OPEN
	file.store_buffer(bytes)
	var write_error := file.get_error()
	file.flush()
	var flush_error := file.get_error()
	var complete := write_error == OK and flush_error == OK and file.get_position() == bytes.size()
	file.close()
	if complete:
		var check := FileAccess.open(temporary, FileAccess.READ)
		complete = check != null
		if check != null:
			complete = check.get_length() == bytes.size() and check.get_buffer(bytes.size()) == bytes
			check.close()
	var checked := ConfigFile.new()
	complete = complete and checked.load(temporary) == OK and _usable_document(checked)
	if not complete:
		DirAccess.remove_absolute(temporary)
		return ERR_FILE_CANT_WRITE
	var previous := OVERRIDE_PATH + ".previous"
	var moved_previous := false
	if FileAccess.file_exists(OVERRIDE_PATH):
		var current := ConfigFile.new()
		if current.load(OVERRIDE_PATH) == OK and _usable_document(current):
			if FileAccess.file_exists(previous) and DirAccess.remove_absolute(previous) != OK:
				DirAccess.remove_absolute(temporary)
				return ERR_FILE_CANT_WRITE
			if DirAccess.rename_absolute(OVERRIDE_PATH, previous) != OK:
				DirAccess.remove_absolute(temporary)
				return ERR_FILE_CANT_WRITE
			moved_previous = true
		elif DirAccess.remove_absolute(OVERRIDE_PATH) != OK:
			# Never displace a valid recovery copy with a damaged canonical file.
			DirAccess.remove_absolute(temporary)
			return ERR_FILE_CANT_WRITE
	if DirAccess.rename_absolute(temporary, OVERRIDE_PATH) != OK:
		if moved_previous:
			DirAccess.rename_absolute(previous, OVERRIDE_PATH)
		DirAccess.remove_absolute(temporary)
		return ERR_FILE_CANT_WRITE
	# Retaining the previous generation is intentional: readers can recover it
	# if a later load encounters a damaged canonical document.
	return OK


static func apply_environment(environment: Environment) -> void:
	if environment == null:
		return
	var cfg := values()
	if cfg.is_empty():
		return
	environment.volumetric_fog_enabled = bool(cfg.get("volumetric_fog", false))
	environment.ssao_enabled = bool(cfg.get("ssao", false))
	environment.ssil_enabled = bool(cfg.get("ssil", false))
	environment.glow_enabled = bool(cfg.get("glow", false))
	environment.volumetric_fog_density = float(cfg.get("volumetric_fog_density", 0.0))
	environment.volumetric_fog_length = float(cfg.get("volumetric_fog_length", 64.0))
	environment.volumetric_fog_sky_affect = float(cfg.get("volumetric_fog_sky_affect", 0.0))


static func apply_viewport(viewport: Viewport) -> void:
	if viewport == null:
		return
	var cfg := values()
	var distances: Variant = _config.get("draw_distance_options", {})
	if distances is Dictionary:
		var distance: Variant = distances.get(cfg.get("draw_distance", "Normal"), {})
		if distance is Dictionary:
			viewport.mesh_lod_threshold = float(distance.get("lod_threshold", 1.0))
	var shadows: Variant = _config.get("shadow_quality_options", {})
	if shadows is Dictionary:
		var quality: Variant = shadows.get(cfg.get("shadow_quality", "Medium"), {})
		if quality is Dictionary:
			var profile := str(cfg.get("shadow_quality", "Medium"))
			if profile != _applied_shadow_profile:
				RenderingServer.directional_shadow_atlas_set_size(int(quality.get("atlas_size", 2048)), false)
				RenderingServer.directional_soft_shadow_filter_set_quality(int(quality.get("filter_quality", 2)) as RenderingServer.ShadowQuality)
				_applied_shadow_profile = profile


static func apply_sun(sun: DirectionalLight3D) -> void:
	if sun == null:
		return
	# Terrain3D's Compatibility path samples the sun shadow map even when
	# shading is disabled. Keep the map valid; zero opacity removes visible
	# shadows without triggering the known fully-black ground defect.
	# Off consequently retains the minimum atlas cost on this path.
	if values().get("shadow_quality", "Medium") == "Off":
		sun.shadow_enabled = true
		sun.shadow_opacity = 0.0


static func apply_camera(camera: Camera3D) -> void:
	if camera == null:
		return
	var cfg := values()
	var distances: Variant = _config.get("draw_distance_options", {})
	if distances is Dictionary:
		var distance: Variant = distances.get(cfg.get("draw_distance", "Normal"), {})
		if distance is Dictionary:
			# A realm whose identity is its vista (Cloudreach: the cloud sea,
			# far shelves and the Aviary sightline sit 300-900 m out) declares a
			# floor on its own camera; the preset still sets every farther value.
			var vista_floor := float(camera.get_meta(&"vista_far_floor_m", 0.0))
			camera.far = maxf(camera.near + 1.0, maxf(float(distance.get("far", camera.far)), vista_floor))

